#!/usr/bin/env python3
"""check.py -- exact re-derivation of the twisted-pair (E1/2 + E5/2) line-branch selection and
characteristic-zero unit-ideal certificates for the eight axis-moving branches.

Setting (supplied, not derived): 27-point cell {-1,0,1}^3, amplitudes A_n in M_4(C), covariance
A_{Rn} = D(R) A_n D(R)^dag under the 24 proper cubic rotations with D = E1/2 (+) (E1/2 x sign),
sign = -1 on the C4 generators; unitarity  sum_n A_n A_{n-m}^dag = delta_{m,0} 1;  U(0)=sum_n A_n = 1.
Everything below is exact (Fractions, a hand-written Q(zeta_8) class) except the labelled
numerical section.  Embedded data: the covariant basis tables M and the layered certificates.
"""
import sys, time, itertools, json, zlib, base64, random
from fractions import Fraction as F
import numpy as np
T0 = time.time()
PASS = 0; FAIL = 0
def rep(ok, msg):
    global PASS, FAIL
    if ok: PASS += 1
    else: FAIL += 1
    print(('PASS ' if ok else 'FAIL ') + msg, flush=True)
def tt(): return '%.0fs' % (time.time() - T0)

# ---------------------------------------------------------------- Q(zeta_8) arithmetic
# element = tuple (c0,c1,c2,c3) = c0 + c1 z + c2 z^2 + c3 z^3, z^4 = -1, z = exp(i pi/4)
Z0 = (F(0),)*4; Z1 = (F(1), F(0), F(0), F(0)); ZI = (F(0), F(0), F(1), F(0)); ZZ = (F(0), F(1), F(0), F(0))
def zadd(a, b): return tuple(x + y for x, y in zip(a, b))
def zneg(a): return tuple(-x for x in a)
def zsc(a, c): return tuple(x * c for x in a)
def zmul(a, b):
    r = [F(0)]*4
    for i in range(4):
        if a[i] == 0: continue
        for j in range(4):
            k = i + j
            if k >= 4: r[k-4] -= a[i]*b[j]
            else: r[k] += a[i]*b[j]
    return tuple(r)
def zconj(a): return (a[0], -a[3], -a[2], -a[1])
S2 = zadd(ZZ, zneg(zmul(zmul(ZZ, ZZ), ZZ)))          # sqrt2 = z - z^3
def zsum(it):
    r = Z0
    for x in it: r = zadd(r, x)
    return r
def mm(A, B):
    n = len(A); m = len(B[0]); k = len(B)
    return [[zsum(zmul(A[i][c], B[c][j]) for c in range(k)) for j in range(m)] for i in range(n)]
def mdag(A): return [[zconj(A[j][i]) for j in range(len(A))] for i in range(len(A[0]))]
def mscale(A, c): return [[zmul(c, x) for x in row] for row in A]
def meq(A, B): return all(x == y for ra, rb in zip(A, B) for x, y in zip(ra, rb))
def mneg(A): return [[zneg(x) for x in r] for r in A]
def bdiag(A, B):
    n = len(A); m = len(B)
    return [A[i] + [Z0]*m for i in range(n)] + [[Z0]*n + B[i] for i in range(m)]
def eye(n): return [[Z1 if i == j else Z0 for j in range(n)] for i in range(n)]

# ---------------------------------------------------------------- group
zinv = zneg(zmul(zmul(ZZ, ZZ), ZZ))                      # z^-1 = -z^3
dz = [[zinv, Z0], [Z0, ZZ]]                               # exp(-i pi/2 Jz)
half_s2 = zsc(S2, F(1, 2))                                # 1/sqrt2
mi = zneg(ZI)
dx = [[half_s2, zmul(half_s2, mi)], [zmul(half_s2, mi), half_s2]]   # exp(-i pi/2 Jx)
Dz4 = bdiag(dz, mneg(dz)); Dx4 = bdiag(dx, mneg(dx))     # sign (-1) on the C4 generators in the second block
RZ = ((0, -1, 0), (1, 0, 0), (0, 0, 1)); RX = ((1, 0, 0), (0, 0, -1), (0, 1, 0))
def rmul(A, B): return tuple(tuple(sum(A[i][k]*B[k][j] for k in range(3)) for j in range(3)) for i in range(3))
def rapply(R, n): return tuple(sum(R[i][k]*n[k] for k in range(3)) for i in range(3))
ID3 = ((1, 0, 0), (0, 1, 0), (0, 0, 1))
G = {ID3: eye(4)}
frontier = [ID3]
while frontier:
    nxt = []
    for R in frontier:
        for R2, D2 in ((RZ, Dz4), (RX, Dx4)):
            R3 = rmul(R, R2)
            if R3 not in G:
                G[R3] = mm(G[R], D2); nxt.append(R3)
    frontier = nxt
rep(len(G) == 24, 'group closure: 24 proper cubic rotations generated by (RZ,Dz),(RX,Dx) [%s]' % tt())
# projective consistency: D(R1) D(R2) = +-D(R1 R2) with ONE sign for both blocks (the sign twist is a genuine character)
ok = True
for R1 in G:
    for R2 in G:
        P = mm(G[R1], G[R2]); Q = G[rmul(R1, R2)]
        if not (meq(P, Q) or meq(P, mneg(Q))): ok = False
rep(ok, 'D is a projective representation of O on C^4 (all 576 products equal +-D(R1R2))')
uni = all(meq(mm(D, mdag(D)), eye(4)) for D in G.values())
rep(uni, 'all 24 lifts are exactly unitary')
# characters: commutant dimension (1/24) sum |tr D|^2 = 2 (E1/2 and E5/2 inequivalent) -> Schur: U(0) = diag(c1 1_2, c2 1_2)
def tr(D): return zsum(D[i][i] for i in range(4))
tot = F(0)
for D in G.values():
    t = tr(D); n2 = zmul(t, zconj(t))
    assert n2[1] == 0 and n2[2] == 0 and n2[3] == 0
    tot += n2[0]
rep(tot / 24 == 2, 'commutant of D has dimension (1/24) sum|tr D|^2 = 2 (two inequivalent 2-dim blocks): U(0) = diag(c1,c2)')

