DATA = None
def load_data():
    global DATA
    DATA = json.loads(zlib.decompress(base64.b64decode(DATA_B64)).decode())
cell = [tuple(v) for v in itertools.product((-1, 0, 1), repeat=3)]
cellset = set(cell)
# ---------------------------------------------------------------- covariant family (tables M) : verify, do not trust
def gparse(c):   # Gaussian rational (F,F) from strings
    return (F(c[0]), F(c[1]))
def to_z8(g):    # Gaussian -> Q(zeta8): re + im * z^2
    return (g[0], F(0), g[1], F(0))
def build_family():
    Mt = {}      # j -> {site: 4x4 z8 matrix}
    for n, j, mat in DATA['M']:
        Mt.setdefault(j, {})[tuple(n)] = [[to_z8(gparse(c)) for c in row] for row in mat]
    return Mt
def check_family(Mt):
    NPj = len(Mt)
    ok = True
    for j, sites in Mt.items():
        for n, mat in sites.items():
            for R, D in G.items():
                m = rapply(R, n)
                img = mm(mm(D, mat), mdag(D))
                if m not in sites or not meq(img, sites[m]): ok = False
    rep(ok, 'family tables: every basis element is exactly covariant, A_{Rn} = D A_n D^dag, with support on one full orbit (%d complex parameters)' % NPj)
    # support: each param supported on a single orbit
    # dimension of the covariant space by the trace formula: (1/24) sum_R fix(R) |tr D_R|^2
    tot = F(0)
    for R, D in G.items():
        fix = sum(1 for n in cell if rapply(R, n) == n)
        t = tr(D); n2 = zmul(t, zconj(t)); tot += fix * n2[0]
    dim = tot / 24
    rep(dim == NPj == 22, 'dimension of the covariant family = (1/24) sum_R fix(R)|tr D_R|^2 = %s equals the number of tables %d' % (dim, NPj))
    # complex linear independence of the tables (Gaussian elimination over Q(i))
    vecs = []
    for j in sorted(Mt):
        v = []
        for n in cell:
            mat = Mt[j].get(n)
            for a in range(4):
                for b in range(4):
                    z = mat[a][b] if mat else Z0
                    assert z[1] == 0 and z[3] == 0
                    v.append((z[0], z[2]))
        vecs.append(v)
    def gmul(a, b): return (a[0]*b[0]-a[1]*b[1], a[0]*b[1]+a[1]*b[0])
    def ginv(a):
        d = a[0]*a[0]+a[1]*a[1]; return (a[0]/d, -a[1]/d)
    rows = []
    for v in vecs:
        w = list(v)
        for pv, pc in rows:
            if w[pc] != (0, 0):
                f = gmul(w[pc], ginv(pv[pc]))
                w = [(x[0]-gmul(f, y)[0], x[1]-gmul(f, y)[1]) for x, y in zip(w, pv)]
        nz = [i for i, x in enumerate(w) if x != (0, 0)]
        if nz: rows.append((w, nz[0]))
    rep(len(rows) == 22, 'the 22 tables are linearly independent over Q(i) (rank %d) -> they span the whole covariant family' % len(rows))
    return NPj

# ---------------------------------------------------------------- axis line lemma data
half = F(1, 2)
def proj(blk, s):
    P = [[Z0]*4 for _ in range(4)]
    for a in range(2):
        for b in range(2):
            v = half * (s if a != b else 1)
            P[2*blk+a][2*blk+b] = (v, F(0), F(0), F(0))
    return P
PK = [proj(0, 1), proj(0, -1), proj(1, 1), proj(1, -1)]     # eigenlines of the C4(x) lift: (1,+-1)/sqrt2 in each block
def axis_checks():
    ok = all(meq(mm(P, P), P) and meq(mdag(P), P) for P in PK)
    ok = ok and all(meq(mm(PK[i], PK[j]), [[Z0]*4]*4) for i in range(4) for j in range(4) if i != j)
    rep(ok, 'axis eigenlines P_0..P_3 of the C4(x) lift: orthogonal rank-1 projectors in the two blocks')
    # eigenvalues of Dx4 on the lines are four distinct elements of Q(zeta8)
    lam = []
    for P in PK:
        DP = mm(Dx4, P)
        # find lambda with DP = lambda P
        for a in range(4):
            for b in range(4):
                if P[a][b] != Z0:
                    # lambda = DP[a][b] / P[a][b]  (P[a][b] is rational)
                    l = zsc(DP[a][b], 1 / P[a][b][0]); break
            else: continue
            break
        lam.append(l)
        assert meq(DP, mscale(P, l))
    rep(len(set(lam)) == 4, 'C4(x) lift has four DISTINCT eigenvalues on the four lines -> U(t e_x) is diagonal in this basis (Schur)')
    # C2(y) pairing
    R2y = ((-1, 0, 0), (0, 1, 0), (0, 0, -1)); D = G[R2y]
    perm = []
    for P in PK:
        Q = mm(mm(D, P), mdag(D))
        idx = [i for i in range(4) if meq(Q, PK[i])]
        perm.append(idx[0] if idx else None)
    rep(perm == [1, 0, 3, 2], 'C2(y) lift maps line 0<->1 and 2<->3 exactly (reverses J_x in each block): forces m=(a,-a,b,-b)')
G_ = None
def c3_check():
    D3 = G[((0, 0, 1), (1, 0, 0), (0, 1, 0))]
    P = mm(D3, D3); Q = mm(zsum_m(P, mneg(D3)), eye(4))
    ok = meq(zsum_m(zsum_m(P, mneg(D3)), eye(4)), [[Z0]*4]*4)
    t = tr(D3)
    rep(ok and t == (F(2), F(0), F(0), F(0)), 'C3 lift about (1,1,1) satisfies D^2 - D + 1 = 0 and tr D = 2: eigenvalues exp(+-i pi/3) each with multiplicity TWO -> no 1-dim eigenlines, so no monomial lemma on the body diagonal')
def zsum_m(A, B): return [[zadd(x, y) for x, y in zip(ra, rb)] for ra, rb in zip(A, B)]
def gram_Mt_forms(Mt):
    NPj = len(Mt)
    # per site, per (a,b): list of (j, Gaussian) with M[j][site][a][b] != 0   (values are in Q(i): coefficients 0 and 2)
    info = {n: [[[] for _ in range(4)] for _ in range(4)] for n in cell}
    for j, sites in Mt.items():
        for n, mat in sites.items():
            for a in range(4):
                for b in range(4):
                    z = mat[a][b]
                    if z != Z0: info[n][a][b].append((j, (z[0], z[2])))
    return info

def axis_rows(m, info, NPj):
    rows = []
    for r in (-1, 0, 1):
        T = [[sum((PK[k][a][b][0] for k in range(4) if m[k] == r), F(0)) for b in range(4)] for a in range(4)]
        for a in range(4):
            for b in range(4):
                rr = [F(0)]*(2*NPj + 1); ri = [F(0)]*(2*NPj + 1)
                for n in cell:
                    if n[0] != r: continue
                    for j, g in info[n][a][b]:
                        rr[j] += g[0]; rr[NPj + j] -= g[1]
                        ri[j] += g[1]; ri[NPj + j] += g[0]
                rr[-1] = T[a][b]; ri[-1] = F(0)
                rows.append(rr); rows.append(ri)
    return rows
def rref(rows, ncols):
    A = [r[:] for r in rows]
    piv = []; ri = 0
    for c in range(ncols):
        p = None
        for i in range(ri, len(A)):
            if A[i][c] != 0: p = i; break
        if p is None: continue
        A[ri], A[p] = A[p], A[ri]
        f = A[ri][c]; A[ri] = [x / f for x in A[ri]]
        for i in range(len(A)):
            if i != ri and A[i][c] != 0:
                g = A[i][c]; A[i] = [x - g*y for x, y in zip(A[i], A[ri])]
        piv.append(c); ri += 1
    cons = all(A[i][ncols] == 0 for i in range(ri, len(A)))
    return A[:ri], piv, cons
def exhaustive_axis(info, NPj):
    good = {}
    ranks = set()
    for m in itertools.product((-1, 0, 1), repeat=4):
        A, piv, cons = rref(axis_rows(m, info, NPj), 2*NPj)
        if cons: good[m] = (A, piv); ranks.add(len(piv))
    shape = sorted(good) == sorted((a, -a, b, -b) for a in (-1, 0, 1) for b in (-1, 0, 1))
    rep(len(good) == 9 and shape, 'exhaustive exact linear selection: of all 81 axis-exponent vectors m in {-1,0,1}^4, exactly 9 give a consistent linear system, namely (a,-a,b,-b)')
    rep(ranks == {12}, 'each of the 9 consistent branches has 12 independent linear constraints on the 44 real unknowns -> 32 free unknowns')
    return good

# ---------------------------------------------------------------- branch affine spaces and unitarity polynomials
def branch_map(A, piv, NPj):
    """w (44 real unknowns) as affine forms {0:const, i+1: coeff} in the free unknowns t_0..t_31 (free = non-pivot columns ascending)"""
    ncol = 2*NPj
    free = [c for c in range(ncol) if c not in piv]
    tid = {c: i for i, c in enumerate(free)}
    w = {}
    for c in free: w[c] = {tid[c] + 1: F(1)}
    for row, pc in zip(A, piv):
        f = {}
        if row[ncol] != 0: f[0] = row[ncol]
        for c in free:
            if row[c] != 0: f[tid[c] + 1] = -row[c]
        w[pc] = f
    return free, w
def fadd(f, g, c=F(1)):
    r = dict(f)
    for k, v in g.items():
        nv = r.get(k, F(0)) + c * v
        if nv == 0: r.pop(k, None)
        else: r[k] = nv
    return r
def fscale(f, c): return {k: v*c for k, v in f.items()} if c != 0 else {}
def A_forms(info, w, NPj):
    """A[n][a][b] = (re_form, im_form) in t"""
    out = {}
    for n in cell:
        out[n] = []
        for a in range(4):
            row = []
            for b in range(4):
                re = {}; im = {}
                for j, g in info[n][a][b]:
                    xj = w[j]; yj = w[NPj + j]
                    # (x + i y)(gr + i gi)
                    re = fadd(re, xj, g[0]); re = fadd(re, yj, -g[1])
                    im = fadd(im, xj, g[1]); im = fadd(im, yj, g[0])
                row.append((re, im))
            out[n].append(row)
    return out
def pol_add(p, q, c=F(1)):
    r = dict(p)
    for k, v in q.items():
        nv = r.get(k, F(0)) + c * v
        if nv == 0: r.pop(k, None)
        else: r[k] = nv
    return r
def pol_mul(p, q):
    r = {}
    for m1, v1 in p.items():
        for m2, v2 in q.items():
            m = tuple(sorted(m1 + m2)); nv = r.get(m, F(0)) + v1 * v2
            if nv == 0: r.pop(m, None)
            else: r[m] = nv
    return r
def form2pol(f):
    return {(() if k == 0 else (k - 1,)): v for k, v in f.items()}
def resid_poly(label, Af):
    m, a, b, part = label; m = tuple(m)
    acc = {}
    for n in cell:
        n2 = (n[0]-m[0], n[1]-m[1], n[2]-m[2])
        if n2 not in cellset: continue
        for c in range(4):
            r1, i1 = Af[n][a][c]; r2, i2 = Af[n2][b][c]
            P1r, P1i, P2r, P2i = form2pol(r1), form2pol(i1), form2pol(r2), form2pol(i2)
            if part == 0:
                acc = pol_add(acc, pol_mul(P1r, P2r)); acc = pol_add(acc, pol_mul(P1i, P2i))
            else:
                acc = pol_add(acc, pol_mul(P1i, P2r)); acc = pol_add(acc, pol_mul(P1r, P2i), F(-1))
    if part == 0 and m == (0, 0, 0) and a == b:
        acc = pol_add(acc, {(): F(1)}, F(-1))
    return acc
def parse_pol(lst):
    return {tuple(mo): F(c) for mo, c in lst}
def replay(branch, gens, mutate=None):
    """layered certificate replay: returns the final polynomial. gens: list of polynomials (compact ids)."""
    prev = {i: p for i, p in enumerate(gens)}
    for L, (kind, outs) in enumerate(branch['levels']):
        new = {}
        for j, ent in outs:
            s = {}
            for i, q in ent:
                q = parse_pol(q)
                if mutate is not None: q = mutate(L, j, i, q)
                s = pol_add(s, pol_mul(q, prev[i]))
            new[j] = s
        prev = new
    return prev[branch['final']]

def evalpol(p, pt):
    s = F(0)
    for mo, c in p.items():
        t = c
        for v in mo: t *= pt[v]
        s += t
    return s

# ---------------------------------------------------------------- certificates
def certificates(good, info, NPj):
    branches = DATA['branches']
    ctx = {}
    for m in sorted(good):
        A, piv = good[m]
        free, w = branch_map(A, piv, NPj)
        Af = A_forms(info, w, NPj)
        ctx[m] = (free, w, Af)
    results = {}
    for m in sorted(good):
        if m == (0, 0, 0, 0): continue
        br = branches[str(m)]
        t1 = time.time()
        free, w, Af = ctx[m]
        gens = [resid_poly((tuple(lbl[0]), lbl[1], lbl[2], lbl[3]), Af) for lbl in br['glabels']]
        fin = replay(br, gens)
        ok = (fin == {(): F(1)})
        results[m] = (br, gens)
        rep(ok, 'branch m=%s: layered cofactor certificate over Q (%d generators, %d levels) replays to exactly 1 -> unit ideal in char 0 [%s, %.0fs]' % (str(m), len(gens), len(br['levels']), tt(), time.time() - t1))
    return ctx, results

def replay_point(branch, gens, pt, mutate=None):
    """same replay, but every polynomial is evaluated at the rational point pt (cheap, used for deliberately wrong certificates)"""
    prev = {i: evalpol(p, pt) for i, p in enumerate(gens)}
    for L, (kind, outs) in enumerate(branch['levels']):
        new = {}
        for j, ent in outs:
            s_ = F(0)
            for i, q in ent:
                q = parse_pol(q)
                if mutate is not None: q = mutate(L, j, i, q)
                s_ += evalpol(q, pt) * prev[i]
            new[j] = s_
        prev = new
    return prev[branch['final']]
def mutation_controls(ctx, results, info, NPj):
    rnd = random.Random(12345)
    pt = [F(rnd.randint(-40, 40), rnd.randint(1, 9)) for _ in range(32)]
    ms = sorted(results)
    mA, mB = ms[0], ms[3]
    brA, gensA = results[mA]; brB, gensB = results[mB]
    base = replay_point(brA, gensA, pt)
    rep(base == 1, 'control 0: unmutated certificate evaluates to exactly 1 at a random rational point (baseline for the mutations below)')
    first = brA['levels'][0][1][0]; j0 = first[0]; i0 = first[1][0][0]
    def mut(L, j, i, q):
        if L == 0 and j == j0 and i == i0: return pol_add(q, {(): F(1, 7)})
        return q
    rep(replay_point(brA, gensA, pt, mutate=mut) != 1, 'mutation control 1: perturbing one cofactor coefficient destroys the certificate')
    def swp(p):
        r = {}
        for mo, c in p.items(): r[tuple(sorted((1 if v == 0 else 0 if v == 1 else v) for v in mo))] = c
        return r
    rep(replay_point(brA, [swp(g) for g in gensA], pt) != 1, 'mutation control 2: swapping two unknowns t_0<->t_1 inside the generators (variable mis-identification) breaks the certificate')
    n = min(len(gensA), len(gensB))
    try:
        bad = replay_point(brA, gensB[:n], pt) != 1
    except Exception:
        bad = True
    rep(bad, 'mutation control 3: the certificate of branch %s does not certify the generators of branch %s' % (str(mA), str(mB)))
    gensA2 = []
    for g in gensA:
        g2 = dict(g)
        if () in g2: g2[()] = -g2[()]
        gensA2.append(g2)
    rep(replay_point(brA, gensA2, pt) != 1, 'mutation control 4: flipping the sign of the constant term of every generator breaks the certificate')
    # 5. the same certificate replayed on the AXIS-FLAT branch generators must fail (that branch is non-empty)
    free, w, AfF = ctx[(0, 0, 0, 0)]
    gensF = [resid_poly((tuple(lbl[0]), lbl[1], lbl[2], lbl[3]), AfF) for lbl in brA['glabels']]
    rep(replay_point(brA, gensF, pt) != 1, 'mutation control 5: branch %s certificate evaluated on the same-labelled equations of the surviving flat branch does not give 1' % str(mA))

# ---------------------------------------------------------------- the surviving (axis-flat) branch
def flat_branch(ctx, info, Mt, NPj):
    free, w, Af = ctx[(0, 0, 0, 0)]
    # constant walk A_0 = 1 : solve for the origin parameters
    org = [j for j in Mt if (0, 0, 0) in Mt[j]]
    rows = []
    for a in range(4):
        for b in range(4):
            rr = [F(0)]*(2*len(org)+1); ri = [F(0)]*(2*len(org)+1)
            for k, j in enumerate(org):
                z = Mt[j][(0, 0, 0)][a][b]; g = (z[0], z[2])
                rr[k] += g[0]; rr[len(org)+k] -= g[1]
                ri[k] += g[1]; ri[len(org)+k] += g[0]
            rr[-1] = F(1) if a == b else F(0); ri[-1] = F(0)
            rows.append(rr); rows.append(ri)
    Ared, piv, cons = rref(rows, 2*len(org))
    assert cons and len(piv) == 2*len(org)
    wv = [F(0)]*(2*NPj)
    for row, pc in zip(Ared, piv):
        val = row[2*len(org)]
        k = pc % len(org); isy = pc >= len(org)
        wv[(NPj if isy else 0) + org[k]] = val
    t0 = [wv[c] for c in free]
    ok = all(sum((v * (t0[k-1] if k else 1) for k, v in w[c].items()), F(0)) == wv[c] for c in range(2*NPj))
    rep(ok, 'constant walk A_0=1 (all other A_n=0) lies in the axis-flat branch (0,0,0,0): its affine map reproduces all 44 unknowns')
    # evaluate A_n(t0)
    def ev(f): return sum((v * (t0[k-1] if k else 1) for k, v in f.items()), F(0))
    okA = True
    for n in cell:
        for a in range(4):
            for b in range(4):
                re = ev(Af[n][a][b][0]); im = ev(Af[n][a][b][1])
                want = F(1) if (n == (0, 0, 0) and a == b) else F(0)
                if re != want or im != 0: okA = False
    rep(okA, 'A_n(t0) is exactly the identity at the origin and zero elsewhere, so U(k)=1: all unitarity equations hold (survivor is non-empty)')
    # tangent dimension at t0
    rows = []
    for mv in itertools.product(range(-2, 3), repeat=3):
        nm = (-mv[0], -mv[1], -mv[2])
        for a in range(4):
            for b in range(4):
                # dR_m[a][b] = dA_m[a][b] + conj(dA_{-m}[b][a])
                rr = [F(0)]*32; ri = [F(0)]*32
                if mv in cellset:
                    re, im = Af[mv][a][b]
                    for k, v in re.items():
                        if k: rr[k-1] += v
                    for k, v in im.items():
                        if k: ri[k-1] += v
                if nm in cellset:
                    re, im = Af[nm][b][a]
                    for k, v in re.items():
                        if k: rr[k-1] += v
                    for k, v in im.items():
                        if k: ri[k-1] -= v
                rows.append(rr + [F(0)]); rows.append(ri + [F(0)])
    _, piv, _ = rref(rows, 32)
    tdim = 32 - len(piv)
    rep(tdim == 16, 'Zariski tangent space of the survivor at the constant walk has dimension %d (exact rank; NOT a local-dimension claim)' % tdim)
    # branch flatness: B_{+-1} = 0, B_0 = 1 identically on the affine space
    flat = True
    for r in (-1, 0, 1):
        for a in range(4):
            for b in range(4):
                re = {}; im = {}
                for n in cell:
                    if n[0] != r: continue
                    re = fadd(re, Af[n][a][b][0]); im = fadd(im, Af[n][a][b][1])
                want = F(1) if (r == 0 and a == b) else F(0)
                if im or (re != ({0: want} if want else {})): flat = False
    rep(flat, 'on the survivor B_{-1}=B_{+1}=0 and B_0=1 identically: U(t e_x)=1, hence dU/dk(0)=0 along every axis (no linear Dirac term)')
    # exact linear consequences of unitarity inside the survivor
    br = DATA['flat']
    gens = [resid_poly((tuple(lbl[0]), lbl[1], lbl[2], lbl[3]), Af) for lbl in br['glabels']]
    prev = {i: p for i, p in enumerate(gens)}
    seedset = {}
    for L, (kind, outs) in enumerate(br['levels']):
        new = {}
        for j, ent in outs:
            s_ = {}
            for i, q in ent: s_ = pol_add(s_, pol_mul(parse_pol(q), prev[i]))
            new[j] = s_
        prev = new
        for (Ls, ls) in br['seeds']:
            if Ls == L: seedset[(Ls, ls)] = prev[ls]
    lins = list(seedset.values())
    okdeg = all(max((len(m_) for m_ in p), default=0) <= 1 for p in lins)
    # rank of the affine-linear consequences (as vectors over 1,t_0..t_31)
    rows_ = []
    for p in lins:
        r_ = [F(0)]*33
        for mo, c in p.items():
            if len(mo) == 0: r_[32] += c
            elif len(mo) == 1: r_[mo[0]] += c
        rows_.append(r_)
    _, pv_, _ = rref(rows_, 33)
    rep(okdeg and len(pv_) == 14, 'survivor: unitarity implies %d independent affine-linear equations on the 32 unknowns (replayed exactly), so the survivor lies in an 18-dimensional affine subspace' % len(pv_))
    return t0

# ---------------------------------------------------------------- numerical, unrestricted search (labelled CHECKED-numerical)
def numeric_search(Mt, NPj, good):
    from scipy.optimize import least_squares
    sites = cell
    Mn = np.zeros((NPj, 27, 4, 4), complex)
    for j, st in Mt.items():
        for n, mat in st.items():
            for a in range(4):
                for b in range(4):
                    z = mat[a][b]; Mn[j, sites.index(n), a, b] = complex(float(z[0]), float(z[2]))
    ks = [2*np.pi*np.array(s)/5 for s in itertools.product(range(5), repeat=3)]
    E = np.array([[np.exp(1j*np.dot(k, n)) for n in sites] for k in ks])
    def Amat(w): return np.tensordot(w[:NPj] + 1j*w[NPj:], Mn, axes=(0, 0))
    def Uof(A, E_): return np.einsum('kn,nab->kab', E_, A)
    def full_res(w):
        U = Uof(Amat(w), E)
        R = np.einsum('kab,kcb->kac', U, U.conj()) - np.eye(4)
        U0 = Amat(w).sum(0) - np.eye(4)
        v = np.concatenate([R.ravel(), U0.ravel()])
        return np.concatenate([v.real, v.imag])
    kx = [np.array([t, 0, 0]) for t in np.linspace(0, np.pi, 11)]
    Ex = np.array([[np.exp(1j*np.dot(k, n)) for n in sites] for k in kx])
    rng = np.random.default_rng(20261016)
    conv = []; t1 = time.time()
    for s in range(120):
        if time.time() - t1 > 80: break
        w0 = rng.normal(size=2*NPj) * 0.6
        r = least_squares(full_res, w0, method='lm', xtol=1e-15, ftol=1e-15, gtol=1e-15, max_nfev=300)
        if np.abs(r.fun).max() < 1e-9: conv.append(r.x)
    nflat = 0; nconst = 0; devs = []
    for w in conv:
        A = Amat(w); U = Uof(A, Ex)
        dev = np.abs(U - np.eye(4)).max(); devs.append(dev)
        off = max(np.abs(A[i]).max() for i in range(27) if sites[i] != (0, 0, 0))
        if dev < 1e-5: nflat += 1
        if off > 1e-4: nconst += 1
    rep(len(conv) >= 1 and nflat == len(conv), 'numerical unrestricted search (44 real unknowns, U(0)=1, unitarity): %d converged solutions, %d of them axis-flat (max axis deviation %.1e), %d non-constant [CHECKED-numerical; corroboration only]' % (len(conv), nflat, max(devs) if devs else -1, nconst))
    rep(nconst >= 1, 'the axis-flat survivor contains non-constant walks (so the exclusion is of axis motion, not of all non-trivial walks)')
    # restricted search on a moving branch: force B_r = target
    out = {}
    for m in [(-1, 1, 0, 0), (-1, 1, -1, 1), (0, 0, 1, -1)]:
        T = {r: sum((np.array([[float(PK[k][a][b][0]) for b in range(4)] for a in range(4)]) for k in range(4) if m[k] == r), np.zeros((4, 4))) for r in (-1, 0, 1)}
        Bsel = {r: [i for i in range(27) if sites[i][0] == r] for r in (-1, 0, 1)}
        def res_b(w, T=T, Bsel=Bsel):
            A = Amat(w); parts = [full_res(w)]
            for r in (-1, 0, 1):
                d = A[Bsel[r]].sum(0) - T[r]; parts += [d.real.ravel(), d.imag.ravel()]
            return np.concatenate(parts)
        best = 1e9; nconv = 0
        for s in range(15):
            w0 = rng.normal(size=2*NPj) * 0.6
            r = least_squares(res_b, w0, method='lm', xtol=1e-15, ftol=1e-15, gtol=1e-15, max_nfev=300)
            best = min(best, np.abs(r.fun).max()); nconv += np.abs(r.fun).max() < 1e-9
        out[m] = (best, nconv)
    rep(all(v[1] == 0 for v in out.values()), 'numerical search restricted to moving branches %s: no convergence in 15 starts each (best sup-residuals %s) [CHECKED-numerical; no proof]' % (sorted(out), ['%.2g' % v[0] for v in out.values()]))

# ---------------------------------------------------------------- simultaneous-variable converter and its mutant
def converter_controls(ctx, results, t0, NPj):
    import sympy as sp, re as _re
    free, w, Af = ctx[(0, 0, 0, 0)]
    # generators of the flat branch: the first 40 unitarity residuals with several unknowns
    labels = [((0, 0, 0), a, b, p) for a in range(4) for b in range(a, 4) for p in (0, 1)]
    labels += [(mv, a, b, p) for mv in ((1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0), (0, 1, 1)) for a in range(4) for b in range(4) for p in (0, 1)]
    polys = []
    for lb in labels:
        P = resid_poly(lb, Af)
        if P: polys.append(P)
    polys = polys[:60]
    # original unknowns are named x_j / y_j (real); the free ones are the columns in `free`
    names = [('x%d' % c) if c < NPj else ('y%d' % (c - NPj)) for c in free]
    X = sp.symbols(' '.join(names), real=True)
    X = list(X) if isinstance(X, (tuple, list)) else [X]
    def topoly(P):
        e = 0
        for mo, c in P.items():
            term = sp.Rational(c.numerator, c.denominator)
            for v in mo: term = term * X[v]
            e += term
        return e
    exprs = [topoly(P) for P in polys]
    pt = {X[i]: sp.Rational(t0[i].numerator, t0[i].denominator) for i in range(len(X))}
    rep(all(sp.expand(e.subs(pt)) == 0 for e in exprs), 'converter control setup: %d flat-branch equations written in unknowns named x_i, y_i vanish at the constant walk' % len(exprs))
    n = len(X)
    Y = sp.symbols('zz0:%d' % n, real=True)
    def conv_simul(e): return sp.expand(e.subs(dict(zip(X, Y)), simultaneous=True))
    # the buggy converter named its targets y0,y1,... (the same family as the unknowns) and substituted one at a time
    Ybug = sp.symbols('y0:%d' % n, real=True)
    def conv_seq(e):
        for f, g in zip(X, Ybug): e = e.subs(f, g)
        return sp.expand(e)
    ptY = {Y[i]: pt[X[i]] for i in range(n)}
    good = [conv_simul(e) for e in exprs]
    rep(all(g.subs(ptY) == 0 for g in good), 'simultaneous-variable converter passes the self-test (converted ideal vanishes at the mapped constant walk)')
    rep(all(sp.expand(g.subs(dict(zip(Y, X)), simultaneous=True) - e) == 0 for g, e in zip(good, exprs)), 'simultaneous converter is a faithful renaming: converting back reproduces every equation exactly')
    ptYb = {Ybug[i]: pt[X[i]] for i in range(n)}
    bad = [conv_seq(e) for e in exprs]
    nbad = sum(1 for b in bad if b.subs(ptYb) != 0)
    nmerge = sum(1 for e, b in zip(exprs, bad) if len(b.free_symbols) < len(e.free_symbols))
    rep(nbad > 0 or nmerge > 0, 'mutation control: the sequential-substitution converter is caught by the self-test or by variable merging (%d of %d equations no longer vanish, %d lose variables)' % (nbad, len(exprs), nmerge))
    # Singular text round trip for the correct converter
    def to_sing(g):
        return '+'.join('(%s)*%s' % (c, '*'.join('%s^%d' % (str(v), k) if k > 1 else str(v) for v, k in zip(Y, mon) if k > 0) or '1') for mon, c in sp.Poly(g, *Y).terms())
    txt = [to_sing(g) for g in good]
    ok = True
    loc = {str(y): y for y in Y}
    for g, tx in zip(good, txt):
        back = sp.sympify(tx.replace('^', '**'), locals=loc)
        if sp.expand(back - g) != 0: ok = False
    rep(ok, 'Singular-syntax text for the simultaneous converter parses back to the same polynomials')

# ---------------------------------------------------------------- main
def main():
    load_data()
    Mt = build_family()
    NPj = check_family(Mt)
    axis_checks()
    c3_check()
    info = gram_Mt_forms(Mt)
    good = exhaustive_axis(info, NPj)
    ctx, results = certificates(good, info, NPj)
